select month(s.opened_date) as opened_month, max(o.discount) - min(o.discount) as discount_range, round((100 * sum(case when o.channel = 'partner' then 1 else 0 end)) / count(*), 1) as pct_partner from orders o join stores s on o.store_id = s.id left join customers c on o.customer_id = c.id group by month(s.opened_date) having round((100 * sum(case when o.channel = 'partner' then 1 else 0 end)) / count(*), 1) > 20 order by pct_partner desc, opened_month desc;
